package com.hmdp.ai.infrastructure.mcp;import com.fasterxml.jackson.databind.JsonNode;import com.hmdp.ai.domain.mcp.McpServer;import com.hmdp.ai.domain.tool.*;import org.springframework.stereotype.Component;@Component public class McpToolProtocolAdapter implements ToolProtocolAdapter {private final McpServerRegistry servers;private final McpToolExecutor executor;public McpToolProtocolAdapter(McpServerRegistry servers,McpToolExecutor executor){this.servers=servers;this.executor=executor;}public ToolProtocol protocol(){return ToolProtocol.MCP;}public ToolResult execute(ToolDefinition d,ToolInvocation i,JsonNode c){long started=System.currentTimeMillis();try{McpServer server=servers.require(i.getContext().getTenantId(),i.getContext().getWorkspaceId(),c.path("serverId").asText());String tool=c.path("toolName").asText();if(tool.isEmpty())throw new IllegalArgumentException("MCP_TOOL_NAME_REQUIRED");return ToolResult.success(executor.execute(server,tool,i.getInput()),System.currentTimeMillis()-started);}catch(Exception e){String code=code(e);return ToolResult.failure(ToolCallStatus.FAILED,code,"MCP tool execution failed",!code.matches("MCP_SERVER_(NOT_FOUND|DISABLED)"));}}private String code(Exception e){Throwable c=e;while(c!=null){if(c.getMessage()!=null&&c.getMessage().matches("[A-Z0-9_]+"))return c.getMessage();c=c.getCause();}return "MCP_CALL_FAILED";}}
